"""Build a dependency-free website that can be uploaded directly to shared hosting."""
import html
import json
import hashlib
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'public'
OUT.mkdir(exist_ok=True)
CONFIG = json.loads((ROOT / 'site.json').read_text())
def e(value): return html.escape(str(value), quote=True)
def asset(path): return path + '?v=' + hashlib.sha256((OUT/path).read_bytes()).hexdigest()[:12]
def billing(path):
    # Deliberately isolated review build. No PHP, account or order endpoints are called.
    if 'domain=transfer' in path: return 'domain-search.html?mode=transfer'
    if 'domain=register' in path or path == 'cart.php': return 'domain-search.html'
    if 'submitticket' in path: return 'contact.html?service=other#enquiry'
    if 'supporttickets' in path: return 'account.html?view=support'
    if 'knowledgebase' in path: return 'support.html#common-questions'
    if 'register' in path: return 'account.html?view=register'
    if 'password' in path: return 'account.html?view=reset'
    return 'account.html'
def catalogue(key):
    return {'monthly':'hosting.html#hosting-plans','yearly':'hosting.html?cycle=yearly#hosting-plans','email':'email.html','ssl':'ssl.html','design':'websites.html#design-packages'}[key]
def btn(label, url, primary=False):
    return f'<a class="btn{" btn-primary" if primary else ""}" href="{url}">{e(label)}</a>'
def icon(name):
    paths = {
        'hosting': '<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M12 6.5h5M12 17.5h5"/>',
        'domain': '<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
        'email': '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',
        'support': '<path d="M4 13v-1a8 8 0 0 1 16 0v1M20 17v2a2 2 0 0 1-2 2h-5"/><rect x="2" y="11" width="4" height="7" rx="2"/><rect x="18" y="11" width="4" height="7" rx="2"/>',
        'design': '<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M8 9v11M6 6.5h.01M9 6.5h.01"/>',
        'lock': '<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
    }
    return f'<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24">{paths[name]}</svg></span>'
def brand():
    return '<a href="index.html" class="brand" aria-label="Mumatec Hosting home"><span class="brand-name" aria-hidden="true">MUMATEC</span><span class="brand-hosting" aria-hidden="true">HOSTING</span></a>'
